/* Protótipo local de UX. Estado transitório e dados de referência; sem autorização de produção.
 * Contratos e handoff: ../etapa-4-experiencia-visual.md e ../sistema-visual.md. */
(function(){
'use strict';
const {games,metadata}=window.LOTTO_REFERENCE;
const {escape:e,validDate,filterDraws,describe,validateDraft}=window.LottoUIModel;
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chart:'M4 20V4 M4 20h17 M9 16v-5 M14 16V7 M19 16V3',star:'m12 3 2.8 5.7 6.3.9-4.5 4.4 1.1 6.2-5.7-3-5.7 3 1.1-6.2L3 9.6l6.3-.9Z',user:'M20 21v-2a7 7 0 0 0-14 0v2 M13 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',users:'M16 21v-2a5 5 0 0 0-10 0v2 M11 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 4a4 4 0 0 1 0 7 M21 21v-2a5 5 0 0 0-3-4.5',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z m-4 9 3 3 5-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',logout:'M9 4H4v16h5 M10 12h11 m-4-4 4 4-4 4',menu:'M4 6h16 M4 12h16 M4 18h16',close:'m6 6 12 12 M18 6 6 18',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',check:'m4 12 5 5L20 6',refresh:'M20 7v5h-5 M4 17v-5h5 M6.1 6.1A8 8 0 0 1 20 12 M4 12a8 8 0 0 0 13.9 5.9',plus:'M12 5v14 M5 12h14',settings:'M4 7h16 M4 17h16 M9 4v6 M16 14v6',source:'M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2',alert:'m12 3 10 18H2Z M12 9v4 M12 17h.01',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3z M12 6v15',beaker:'M9 3h6 M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3 M8 14h8',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5'};
const ico=name=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.grid}"/></svg>`;
const brand=()=>`<a class="brand" href="#/visao-geral" aria-label="LottoBrain, visão geral"><span class="brand-mark" aria-hidden="true">${'<i></i>'.repeat(9)}</span>LottoBrain</a>`;
const state={persona:'member',scenario:'normal',component:'main',page:0,filters:{},drafts:[],jobs:[],requests:[{id:'demo01',name:'Solicitação demonstrativa 01',status:'pending'}],review:'pending'};
let route={},returnFocus=null,toastTimer,pendingFocus=null;
const personaLabels={member:'Usuário aprovado',admin:'Administrador com MFA',pending:'Aguardando aprovação',anonymous:'Visitante',revoked:'Acesso revogado',mfa:'Administrador sem MFA'};
const scenarios={normal:'Conteúdo de referência',loading:'Carregando',empty:'Filtro sem resultados',error:'Falha ao carregar',late:'Atualização atrasada',review:'Dados sob revisão',superseded:'Conjunto superado',blocked:'Fonte indisponível',expired:'Sessão expirada'};
const isAdmin=()=>state.persona==='admin';
const isApproved=()=>['member','admin','mfa'].includes(state.persona)&&state.scenario!=='expired';
const game=()=>games.find(g=>g.slug===(route.path==='admin/revisao'?(state.reviewSlug||games[0].slug):route.slug))||games[0];
const formatDate=(d,short=false)=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR',short?{day:'2-digit',month:'short'}:{day:'2-digit',month:'long',year:'numeric'}):'Não informado';
const fmt=(n,digits=0)=>n==null?'Não disponível':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:digits}).format(n);
const money=(n,c)=>n==null?'Não informado':new Intl.NumberFormat('pt-BR',{style:'currency',currency:c}).format(Number(n));
const latest=g=>g.draws[g.draws.length-1];
const drawName=(g,d)=>g.region==='BR'?`Concurso ${d.id}`:`Sorteio de ${formatDate(d.date,true)}`;
const badge=(text,kind='blue')=>`<span class="badge ${kind}"><i class="badge-dot" aria-hidden="true"></i>${e(text)}</span>`;
const info=(key,label)=>`<button class="info-button" data-action="info" data-key="${key}" aria-label="Entender ${e(label)}">i</button>`;
const button=(text,action,icon='arrow',kind='',extra='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${ico(icon)}<span>${text}</span></button>`;
const notice=(title,text,kind='')=>`<div class="notice ${kind}" role="status">${ico(kind==='red'||kind==='amber'?'alert':'shield')}<div><strong>${title}</strong>${text?`<p>${text}</p>`:''}</div></div>`;
function notify(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
function balls(values,special=false,small=false){return `<div class="balls ${small?'small-balls':''}" aria-label="${special?'Números especiais':'Números principais'}: ${values.join(', ')}">${values.map(n=>`<span class="ball ${special?'special':''}">${String(n).padStart(2,'0')}</span>`).join('')}</div>`;}

// Composição e navegação compartilhadas
function footer(){return `<footer class="footer"><span>Dados de referência até 27 out. 2026 · 30 sorteios por modalidade.</span><span>LottoBrain · protótipo de experiência · 2026</span></footer>`;}
function prototypeBar(){return `<div class="prototype-bar"><span class="prototype-label"><i class="prototype-dot"></i><strong>Protótipo local</strong><span class="prototype-extra">· interações demonstrativas, sem envio de dados</span></span><button data-action="scenarios">${ico('settings')}Cenários e jornadas</button></div>`;}
function nav(){const entries=[['visao-geral','Visão geral','grid'],[`loterias/${game().slug}/resumo`,'Loterias','chart'],[`loterias/${game().slug}/previsoes`,'Previsões','beaker'],['conta','Minha conta','user']];const admin=[['admin/pessoas','Pessoas e acessos','users'],['admin/catalogo','Catálogo de loterias','book'],['admin/execucoes','Execuções','clock'],['admin/revisao','Revisão de dados','shield']];return `<nav aria-label="Navegação principal"><div class="nav-caption">EXPLORAR</div><div class="nav-list">${entries.map(([path,label,icon])=>`<a class="nav-link ${route.path===path||(label==='Loterias'&&route.path.startsWith('loterias')&&route.tab!=='previsoes')?'active':''}" href="#/${path}">${ico(icon)}${label}</a>`).join('')}</div>${isAdmin()?`<div class="nav-caption">ADMINISTRAÇÃO</div><div class="nav-list">${admin.map(([path,label,icon])=>`<a class="nav-link ${route.path===path?'active':''}" href="#/${path}">${ico(icon)}${label}${label==='Pessoas e acessos'&&state.requests.some(r=>r.status==='pending')?'<span class="nav-count">1</span>':''}</a>`).join('')}</div>`:''}</nav>`;}
function shell(body){return `${prototypeBar()}<aside class="sidebar">${brand()}<p class="side-sub">Análise com contexto</p>${nav()}<div class="side-bottom"><div class="private-note"><strong>${ico('lock')} Espaço privado</strong>Acesso por aprovação do administrador.</div><div class="side-profile"><div class="avatar">${isAdmin()?'AD':'US'}</div><div class="profile-meta"><strong>${isAdmin()?'Administrador':'Minha conta'}</strong><span class="muted">Jornada demonstrativa</span></div><button class="icon-button" data-action="logout" aria-label="Sair da conta">${ico('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menu de navegação">${ico('menu')}</button><div class="breadcrumb">Meu espaço <span>/</span> <b>${route.path.startsWith('admin')?'Administração':route.path==='conta'?'Minha conta':route.path==='visao-geral'?'Visão geral':'Loterias'}</b></div></div><div class="topbar-actions"><span class="lock-label">${ico('lock')} Conteúdo privado</span>${badge(isAdmin()?'Administração':'Acesso aprovado','green')}<button class="icon-button" data-action="source" aria-label="Consultar origem dos dados">${ico('source')}</button></div></header><main id="main" class="content" tabindex="-1" style="--accent:${game().color}">${body}${footer()}</main></div>`;}
function pageHeading(title,subtitle,actions='',eyebrow='MEU ESPAÇO'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1">${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function currentFilter(){const g=game();return state.filters[g.slug]||(state.filters[g.slug]={from:g.draws[0].date,to:latest(g).date,limit:30});}
function selectedDraws(){return filterDraws(game(),currentFilter());}
function lotteryTabs(){return `<nav class="lottery-tabs" aria-label="Escolher loteria">${games.map(g=>`<a class="lottery-tab ${g.slug===game().slug?'active':''}" href="#/loterias/${g.slug}/${route.tab||'resumo'}" ${g.slug===game().slug?'aria-current="page"':''}><i class="lottery-dot" style="--game-color:${g.color}"></i>${g.name}</a>`).join('')}</nav>`;}
function subTabs(){return `<div class="subtabs" role="tablist" aria-label="Seções da loteria">${[['resumo','Resumo'],['concursos','Concursos'],['estatisticas','Estatísticas'],['previsoes','Previsões']].map(([key,label])=>`<button id="tab-${key}" class="subtab" role="tab" aria-selected="${route.tab===key}" aria-controls="lottery-panel" tabindex="${route.tab===key?'0':'-1'}" data-action="tab" data-tab="${key}">${label}</button>`).join('')}</div>`;}
function filters(){const f=currentFilter();return `<form class="filterbar" id="filters-form"><div class="field"><label for="period-limit">Janela de análise</label><select id="period-limit" name="limit"><option value="30" ${f.limit===30?'selected':''}>Até 30 sorteios</option><option value="10" ${f.limit===10?'selected':''}>Últimos 10 sorteios</option></select></div><div class="field"><label for="from-date">Data inicial</label><input id="from-date" name="from" type="date" value="${f.from}" required></div><div class="field"><label for="to-date">Data final</label><input id="to-date" name="to" type="date" value="${f.to}" required></div><button class="button primary" type="submit">${ico('settings')}Aplicar filtros</button><div id="filter-error" class="form-error" role="alert" hidden></div></form>`;}

// Resultados, indicadores e gráficos do recorte
function metric(label,value,note,icon){return `<div class="card metric"><div class="metric-label">${label}<span class="metric-icon">${ico(icon)}</span></div><div class="metric-value mono">${value}</div><div class="metric-note">${note}</div></div>`;}
function metrics(draws){const st=describe(draws,game().maximum),top=st.ranked[0];return `<div class="grid metrics">${metric('Sorteios na janela',fmt(st.count),'Amostra, não o histórico inteiro','grid')}${metric('Mais frequente',top&&st.count?String(top.number).padStart(2,'0'):'—',top&&st.count?`${top.count} ocorrências · empates por número`:'Sem observações','chart')}${metric('Média da soma',st.averageSum==null?'—':fmt(st.averageSum,1),'Somente números principais','plus')}${metric('Média de pares',st.averageEven==null?'—':fmt(st.averageEven,1),`Entre os ${game().count} números principais`,'chart')}</div>`;}
function resultCard(g,d){return `<section class="card card-body result-card"><div class="card-header"><div><h2>Último resultado da amostra</h2><p>${g.name} · números publicados pela fonte</p></div>${badge(g.region==='BR'?'Brasil':g.region==='US'?'EUA':'Europa')}</div><div class="result-meta"><span class="result-id">${drawName(g,d)}</span><span class="muted small">${formatDate(d.date)}</span></div><div class="ball-caption">${g.count} números de 1 a ${g.maximum}</div>${balls(d.main)}${g.specialCount?`<div class="ball-group"><div class="ball-caption">${g.specialLabel} · ${g.specialCount} de 1 a ${g.specialMaximum}</div>${balls(d.special,true)}</div>`:''}<div class="result-footer"><span class="source-line">${ico('shield')} Fonte: ${g.sourceLabel}</span><button class="text-button" data-action="draw" data-id="${d.id}">Ver detalhes ${ico('arrow')}</button></div></section>`;}
function rankChart(draws,component='main') {const g=game(),max=component==='special'?g.specialMaximum:g.maximum;const stats=describe(draws,max,component);const rows=stats.ranked.slice(0,10),largest=Math.max(1,...rows.map(r=>r.count)),w=460,h=rows.length*24+29;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Frequência observada: dez números mais presentes em ${draws.length} sorteios"><title>Frequência observada na janela selecionada</title>${[0,.25,.5,.75,1].map(t=>`<line class="gridline" x1="${35+t*365}" y1="0" x2="${35+t*365}" y2="${h-25}"/><text x="${35+t*365}" y="${h-7}" text-anchor="middle">${fmt(largest*t,1)}</text>`).join('')}${rows.map((r,i)=>`<text x="19" y="${i*24+14}" text-anchor="end">${String(r.number).padStart(2,'0')}</text><rect class="track" x="35" y="${i*24+3}" width="365" height="12" rx="3"/><rect class="bar" x="35" y="${i*24+3}" width="${r.count/largest*365}" height="12" rx="3"/><text class="value" x="414" y="${i*24+14}">${r.count}</text>`).join('')}<text x="460" y="${h-7}" text-anchor="end">ocorrências</text></svg><details class="chart-data"><summary>Ver dados do gráfico</summary><table><thead><tr><th>Número</th><th>Ocorrências</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.number}</td><td>${r.count} em ${draws.length} sorteios</td></tr>`).join('')}</tbody></table></details>`;}
function sumChart(draws){const points=describe(draws,game().maximum).sums;if(!points.length)return '';const min=Math.floor(Math.min(...points.map(r=>r.value))/10)*10,max=Math.ceil(Math.max(...points.map(r=>r.value))/10)*10,range=Math.max(1,max-min);const xy=points.map((p,i)=>[38+i/(Math.max(1,points.length-1))*390,190-(p.value-min)/range*155]);return `<svg class="chart" viewBox="0 0 460 239" role="img" aria-label="Soma dos números principais em ordem cronológica, de ${min} a ${max}"><title>Evolução das somas na janela</title>${[0,.5,1].map(t=>`<line class="gridline" x1="38" x2="428" y1="${190-t*155}" y2="${190-t*155}"/><text x="29" y="${194-t*155}" text-anchor="end">${fmt(min+t*range)}</text>`).join('')}<path class="area" d="M${xy[0][0]},190 L${xy.map(p=>p.join(',')).join(' L')} L428,190Z"/><polyline class="trend-line" points="${xy.map(p=>p.join(',')).join(' ')}"/>${xy.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="2.5" fill="${game().color}"><title>${formatDate(points[i].date)}: ${points[i].value}</title></circle>`).join('')}<text x="38" y="218">${formatDate(points[0].date,true)}</text><text x="428" y="218" text-anchor="end">${formatDate(points[points.length-1].date,true)}</text></svg><details class="chart-data"><summary>Ver valores por sorteio</summary><table><thead><tr><th>Data</th><th>Soma</th></tr></thead><tbody>${points.map(p=>`<tr><td>${formatDate(p.date,true)}</td><td>${p.value}</td></tr>`).join('')}</tbody></table></details>`;}
function charts(draws){return `<div class="chart-grid"><section class="card chart-card"><div class="card-header"><div><div class="info-wrap"><h2>Frequência dos números</h2>${info('frequency','a frequência dos números')}</div><p>Os dez mais presentes nos ${draws.length} sorteios selecionados</p></div>${badge('Principais')}</div>${rankChart(draws)}</section><section class="card chart-card"><div class="card-header"><div><div class="info-wrap"><h2>Soma ao longo dos sorteios</h2>${info('sum','a soma dos números')}</div><p>Evolução por sorteio · ordem cronológica</p></div></div>${sumChart(draws)}</section></div>`;}
function drawRows(draws,limit=6){const g=game();const sorted=[...draws].reverse(),start=state.page*limit,rows=sorted.slice(start,start+limit);return `<div class="card"><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Sorteio</th><th>Números principais</th>${g.specialCount?`<th>${g.specialLabel}</th>`:''}<th><span class="small">Detalhes</span></th></tr></thead><tbody>${rows.map(d=>`<tr><td data-label="Sorteio"><strong>${g.region==='BR'?`#${d.id}`:formatDate(d.date,true)}</strong><span class="table-sub">${formatDate(d.date,true)} · ${g.region==='BR'?'Concurso oficial':'Identidade por data'}</span></td><td data-label="Números principais">${balls(d.main,false,true)}</td>${g.specialCount?`<td data-label="${g.specialLabel}">${balls(d.special,true,true)}</td>`:''}<td><div class="table-actions"><button class="icon-button" data-action="draw" data-id="${d.id}" aria-label="Ver detalhes de ${drawName(g,d)}">${ico('chevron')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${Math.min(start+1,draws.length)}–${Math.min(start+limit,draws.length)} de ${draws.length} sorteios da janela</span><div class="pagination-actions"><button class="button" data-action="page" data-delta="-1" ${start===0?'disabled':''}>Anterior</button><button class="button" data-action="page" data-delta="1" ${start+limit>=draws.length?'disabled':''}>Próxima</button></div></div></div>`;}

// Páginas de consulta e seus estados
function overview(){return pageHeading('Seu panorama de loterias','Seis modalidades, com resultados e contexto para explorar.',button('Sobre esta amostra','source','source'),'VISÃO GERAL')+notice('Uma base de referência, seis perfis diferentes.','Os dados exibidos são recortes reais preservados. Datas de referência não representam uma atualização online em andamento.')+`<div class="grid lottery-grid">${games.map(g=>`<article class="card lottery-card" style="--accent:${g.color}"><div class="lottery-card-top"><div class="lottery-symbol">${g.short}</div><div><h2>${g.name}</h2><span class="muted small">${g.count}/${g.maximum}${g.specialCount?` + ${g.specialCount}/${g.specialMaximum}`:''} · ${g.region}</span></div></div><div><span class="ball-caption">${drawName(g,latest(g))}</span>${balls(latest(g).main,false,true)}${g.specialCount?`<div style="margin-top:8px">${balls(latest(g).special,true,true)}</div>`:''}</div><div class="lottery-card-footer"><span>${formatDate(latest(g).date,true)} · ${g.sourceLabel}</span><a class="text-button" href="#/loterias/${g.slug}/resumo">Explorar ${ico('arrow')}</a></div></article>`).join('')}</div>`;}
function scenarioNotice(){if(state.scenario==='late')return notice('Atualização atrasada · cenário demonstrativo','O último resultado confirmado continua disponível. A próxima tentativa segue a política +1h/D+1.','amber');if(state.scenario==='review')return notice('Dados sob revisão · cenário demonstrativo','A amostra anterior permanece consultável. Novas previsões e promoções afetadas aguardam decisão.','amber');if(state.scenario==='superseded')return notice('Conjunto superado · cenário demonstrativo','Você está consultando uma versão anterior, mantida como referência histórica.','amber');if(state.scenario==='blocked')return notice('Fonte indisponível · cenário demonstrativo','Os dados de referência permanecem acessíveis. Não foi realizada uma consulta à fonte.','red');return '';}
function scenarioContent(){if(state.scenario==='loading')return `<section class="card card-body" aria-busy="true" aria-label="Carregando dados"><div class="skeleton title"></div><div class="skeleton"></div><div class="skeleton block"></div><p class="small muted">Carregando resultados… cenário demonstrativo.</p><button class="button" data-action="resume">Encerrar demonstração de carregamento</button></section>`;if(state.scenario==='error')return `<section class="card empty">${ico('alert')}<h2>Não foi possível carregar este conteúdo</h2><p>A última consulta não foi concluída. Seus filtros foram mantidos. Este é um cenário de falha demonstrativo.</p>${button('Tentar novamente','resume','refresh','primary')}</section>`;return null;}
function emptyState(){return `<section class="card empty"><div class="empty-icon">${ico('grid')}</div><h2>Nenhum sorteio neste recorte</h2><p>O período escolhido não encontra registros na amostra. Isso não significa que não houve sorteios fora dela.</p>${button('Restaurar período da amostra','reset-filter','refresh','primary')}</section>`;}
function lottery(){const g=game(),draws=selectedDraws();let body=scenarioContent();if(!body){if(state.scenario==='empty'||!draws.length)body=emptyState();else if(route.tab==='concursos')body=`<div class="section-heading"><h2>Histórico de referência</h2><span class="small muted">${draws.length} sorteios no filtro</span></div>${drawRows(draws)}`;else if(route.tab==='estatisticas')body=statistics(draws);else if(route.tab==='previsoes')body=forecasts();else body=metrics(draws)+`<div class="split">${resultCard(g,draws[draws.length-1])}<section class="card card-body"><div class="card-header"><h2>Como ler este recorte</h2>${info('sample','o recorte de dados')}</div><div class="insight"><span class="insight-icon">${ico('grid')}</span><div><strong>${draws.length} sorteios selecionados</strong><p>${formatDate(draws[0].date,true)} a ${formatDate(draws[draws.length-1].date,true)}. Os filtros alteram as estatísticas.</p></div></div><div class="insight"><span class="insight-icon">${ico('chart')}</span><div><strong>Frequência é uma observação</strong><p>Um número ter aparecido mais vezes não prova maior chance no próximo sorteio.</p></div></div><div class="insight"><span class="insight-icon">${ico('clock')}</span><div><strong>Atualização planejada: +1h / D+1</strong><p>O protótipo não executa coleta. Fonte e disponibilidade serão acompanhadas por modalidade.</p></div></div></section></div>`+charts(draws)+`<div class="section-heading"><h2>Concursos do recorte</h2><button class="text-button" data-action="tab" data-tab="concursos">Ver histórico ${ico('arrow')}</button></div>`+drawRows(draws);}
 return pageHeading(g.name,`${g.count} números de 1 a ${g.maximum}${g.specialCount?` · ${g.specialCount} ${g.specialLabel.toLowerCase()} de 1 a ${g.specialMaximum}`:''}`,button('Origem dos dados','source','source'),'LOTERIAS / ANÁLISE')+lotteryTabs()+subTabs()+scenarioNotice()+(route.tab!=='previsoes'?filters():'')+`<section id="lottery-panel" role="tabpanel" aria-labelledby="tab-${route.tab}" tabindex="0">${body}</section>`;}
function statistics(draws){const g=game(),component=state.component==='special'&&g.specialCount?'special':'main',maximum=component==='main'?g.maximum:g.specialMaximum,st=describe(draws,maximum,component);return metrics(draws)+(g.specialCount?`<div class="segmented" aria-label="Componente analisado"><button data-action="component" data-component="main" class="${component==='main'?'active':''}" aria-pressed="${component==='main'}">Principais</button><button data-action="component" data-component="special" class="${component==='special'?'active':''}" aria-pressed="${component==='special'}">${g.specialLabel}</button></div>`:'')+`<div class="chart-grid"><section class="card chart-card"><div class="card-header"><div><div class="info-wrap"><h2>Frequência observada</h2>${info('frequency','a frequência observada')}</div><p>${component==='main'?'Números principais':g.specialLabel} · contagens na janela</p></div></div>${rankChart(draws,component)}</section><section class="card chart-card"><div class="card-header"><div><div class="info-wrap"><h2>Soma dos principais</h2>${info('sum','a soma dos principais')}</div><p>Sem incluir componentes especiais</p></div></div>${sumChart(draws)}</section></div><section class="card card-body"><div class="card-header"><div><div class="info-wrap"><h2>Todos os números do componente</h2>${info('gap','os intervalos de ocorrência')}</div><p>Toque em um número para ver ocorrências e intervalo no recorte.</p></div></div><div class="stats-grid">${st.frequencies.map(r=>`<button class="number-cell" data-action="number" data-number="${r.number}" data-component="${component}" style="--fill:${Math.round(r.count/Math.max(1,draws.length)*22)}%" aria-label="Número ${r.number}, ${r.count} ${r.count===1?'ocorrência':'ocorrências'}"><b>${String(r.number).padStart(2,'0')}</b><span>${r.count} ${r.count===1?'vez':'vezes'}</span></button>`).join('')}</div></section>`;}
function forecasts(){const blocked=['review','superseded','blocked'].includes(state.scenario);return notice(blocked?'Novas previsões suspensas neste cenário':'Comparação de métodos, com avaliação temporal',blocked?'A demonstração preserva os dados anteriores e informa por que não se deve gerar uma previsão nova.':'Nenhum modelo foi treinado ou avaliado por este protótipo. As métricas abaixo permanecem indisponíveis.',blocked?'amber':'')+`<div class="grid method-grid">${[['Frequência histórica','chart','Referência baseada nas ocorrências anteriores, respeitando o corte temporal.'],['Referência aleatória','grid','Comparação com escolhas uniformes sob o mesmo orçamento de combinações.'],['Modelo supervisionado','beaker','Tentativa de previsão usando somente informações anteriores ao resultado alvo.']].map(([name,icon,text])=>`<section class="card method"><div class="method-symbol">${ico(icon)}</div><h2>${name}</h2><p>${text}</p>${badge('Avaliação ainda não calculada')}</section>`).join('')}</div><section class="card"><div class="card-body"><div class="card-header"><div class="info-wrap"><h2>Comparação e rastreabilidade</h2>${info('forecast','a avaliação dos métodos')}</div></div></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Método</th><th>Acertos médios</th><th>Comparação com referência</th><th>Estado</th></tr></thead><tbody>${['Frequência histórica','Janela móvel','Referência aleatória','Modelo supervisionado'].map(name=>`<tr><td><strong>${name}</strong></td><td data-label="Acertos médios">Não calculado</td><td data-label="Comparação">Não calculada</td><td>${badge('Planejado')}</td></tr>`).join('')}</tbody></table></div></section><section class="card empty" style="margin-top:18px"><div class="empty-icon">${ico('beaker')}</div><h2>Ainda não há previsão emitida</h2><p>Uma previsão futura deverá mostrar método, regra, dados de entrada e horário de emissão. Backtest e previsão emitida terão identificação diferente.</p>${button('Entender a avaliação','info','book','', 'data-key="forecast"')}${isAdmin()?button('Simular solicitação de experimento','new-job','plus','primary',blocked?'disabled':''):''}</section>`;}

// Jornadas administrativas demonstrativas
function people(){return pageHeading('Pessoas e acessos','Aprovação de cadastro, revogação e rastreabilidade.','','ADMINISTRAÇÃO')+notice('Jornada administrativa demonstrativa','As solicitações não representam pessoas reais. Aprovar ou revogar altera somente esta sessão do protótipo.')+`<section class="card"><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Solicitação</th><th>Estado</th><th>Acesso</th><th>Ações</th></tr></thead><tbody>${state.requests.map(r=>`<tr><td><strong>${r.name}</strong><span class="table-sub">Identidade omitida · cenário demonstrativo</span></td><td data-label="Estado">${badge(r.status==='pending'?'Pendente':r.status==='approved'?'Aprovado':'Revogado',r.status==='approved'?'green':r.status==='pending'?'amber':'red')}</td><td data-label="Acesso">${r.status==='approved'?'Usuário · seis loterias':'Conteúdo indisponível'}</td><td><div class="table-actions">${r.status!=='approved'?button('Aprovar','approve-user','check','',`data-id="${r.id}"`):button('Revogar','revoke-user','lock','danger',`data-id="${r.id}"`)}</div></td></tr>`).join('')}</tbody></table></div></section><section class="card card-body" style="margin-top:18px"><h2>Como a aprovação funciona</h2><div class="timeline"><div class="timeline-item"><span class="timeline-dot">1</span><div><strong>Login confirma a identidade</strong><p>Entrar com Google cria uma solicitação, sem conceder acesso aos dados.</p></div></div><div class="timeline-item"><span class="timeline-dot">2</span><div><strong>Administrador decide</strong><p>Aprovação permite leitura. Mudanças sensíveis exigem MFA e ficam auditadas.</p></div></div><div class="timeline-item"><span class="timeline-dot">3</span><div><strong>Revogação bloqueia novas consultas</strong><p>A interface deve informar o motivo de acesso indisponível e permitir sair.</p></div></div></div></section>`;}
function catalog(){return pageHeading('Catálogo de loterias','Modalidades, componentes e perfis de fonte.',button('Cadastrar loteria','new-lottery','plus','primary'),'ADMINISTRAÇÃO')+`<div class="card"><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Modalidade</th><th>Componentes</th><th>Fonte</th><th>Estado no protótipo</th><th>Ações</th></tr></thead><tbody>${games.map(g=>`<tr><td><strong>${g.name}</strong><span class="table-sub">${g.region} · ${g.currency}</span></td><td data-label="Componentes">${g.count}/${g.maximum}${g.specialCount?` + ${g.specialCount}/${g.specialMaximum}`:''}</td><td data-label="Fonte">${g.sourceLabel}</td><td>${badge('Referência real','green')}</td><td><button class="text-button" data-action="catalog-detail" data-slug="${g.slug}">Detalhar ${ico('chevron')}</button></td></tr>`).join('')}${state.drafts.map((d,i)=>`<tr><td><strong>${e(d.name)}</strong><span class="table-sub">${e(d.slug)} · ${e(d.currency)}</span></td><td data-label="Componentes">${d.count}/${d.maximum}${d.specialCount?` + ${d.specialCount}/${d.specialMaximum}`:''}</td><td data-label="Fonte">${e(d.profile)}</td><td>${badge(d.active?'Ativação simulada':'Rascunho simulado',d.active?'green':'amber')}</td><td><button class="text-button" data-action="activate-draft" data-index="${i}">Revisar ativação ${ico('chevron')}</button></td></tr>`).join('')}</tbody></table></div></div>`+notice('Cadastro não inicia coleta automaticamente','O formulário valida a configuração de apresentação. Fonte, adaptador e regras precisam de qualificação antes da ativação real.');}
function newLottery(){return pageHeading('Cadastrar nova loteria','Defina um rascunho com componentes próprios.','','ADMINISTRAÇÃO / CATÁLOGO')+`<div class="two-col"><form class="card card-body" id="lottery-form" novalidate><div class="form-grid"><div class="field full"><label for="lottery-name">Nome da loteria</label><input id="lottery-name" name="name" maxlength="60" required placeholder="Nome da modalidade"></div><div class="field full"><label for="lottery-slug">Identificador</label><input id="lottery-slug" name="slug" maxlength="40" required placeholder="identificador_da_modalidade"><span class="field-help">Letras minúsculas, números e sublinhado. Deve ser único.</span></div><div class="field"><label for="lottery-count">Quantidade de números principais</label><input id="lottery-count" name="count" type="number" min="1" max="100" value="6" required></div><div class="field"><label for="lottery-maximum">Maior número principal</label><input id="lottery-maximum" name="maximum" type="number" min="1" max="100" value="60" required></div><div class="field"><label for="lottery-special-count">Quantidade de especiais</label><input id="lottery-special-count" name="specialCount" type="number" min="0" max="100" value="0"></div><div class="field"><label for="lottery-special-maximum">Maior número especial</label><input id="lottery-special-maximum" name="specialMaximum" type="number" min="0" max="100" value="0"></div><div class="field full"><label for="lottery-special-label">Nome do componente especial</label><input id="lottery-special-label" name="specialLabel" maxlength="40" placeholder="Estrelas, trevos ou outro componente"></div><div class="field"><label for="lottery-currency">Moeda</label><select id="lottery-currency" name="currency"><option>BRL</option><option>USD</option><option>EUR</option></select></div><div class="field"><label for="lottery-profile">Perfil de fonte</label><select id="lottery-profile" name="profile"><option value="A qualificar">A qualificar</option><option>Exportação CAIXA</option><option>OPEN-NY</option><option>SELAE por data</option></select></div><div class="field"><label for="lottery-timezone">Fuso de referência</label><select id="lottery-timezone" name="timezone"><option>America/Sao_Paulo</option><option>America/New_York</option><option>Europe/Paris</option></select></div><div class="field"><label for="lottery-policy">Política de atualização</label><select id="lottery-policy" name="policy"><option>+1h e reconciliação D+1</option><option>Reconciliação diária</option></select></div></div><p id="lottery-error" class="form-error" role="alert"></p><div class="form-actions"><a class="button" href="#/admin/catalogo">Cancelar</a><button class="button primary" type="submit">Salvar rascunho demonstrativo</button></div></form><aside class="card card-body"><h2>Antes de ativar</h2><div class="timeline">${[['1','Regras e vigência','Quantidades, limites, componentes e alterações históricas.'],['2','Fonte e adaptador','Formato suportado, identificação e cobertura verificadas.'],['3','Calendário e qualidade','Fuso, exceções, ausência de dados e revisão de divergências.'],['4','Aprovação explícita','O cadastro por si só não cria uma coleta nem garante dados disponíveis.']].map(([n,title,text])=>`<div class="timeline-item"><span class="timeline-dot">${n}</span><div><strong>${title}</strong><p>${text}</p></div></div>`).join('')}</div></aside></div>`;}
function jobs(){return pageHeading('Execuções e atualização','Acompanhe tentativas, atrasos e recuperação de trabalho.',button('Simular execução','new-job','plus','primary'),'ADMINISTRAÇÃO')+`<div class="grid metrics">${metric('Execuções demonstradas',state.jobs.length,'Somente nesta sessão','clock')}${metric('Política inicial','+1h','Primeira tentativa devida','clock')}${metric('Reconciliação','D+1','09h no fuso da fonte','refresh')}${metric('Consulta real','Nenhuma','Protótipo sem coleta externa','shield')}</div><section class="card">${state.jobs.length?`<div class="table-wrap"><table class="responsive-table"><thead><tr><th>Intenção</th><th>Modalidade</th><th>Estado</th><th>Ação</th></tr></thead><tbody>${state.jobs.map((j,i)=>`<tr><td><strong>${e(j.kind)}</strong><span class="table-sub">Execução demonstrativa ${i+1}</span></td><td data-label="Modalidade">${e(j.game)}</td><td data-label="Estado">${badge(j.done?'Concluída (simulação)':'Solicitada (simulação)',j.done?'green':'amber')}</td><td>${!j.done?button('Simular conclusão','finish-job','check','',`data-index="${i}"`):'<span class="small muted">Amostra preservada</span>'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">${ico('clock')}</div><h2>Nenhuma execução nesta demonstração</h2><p>Simule uma solicitação para percorrer os estados da fila. Não será feita chamada às fontes.</p>${button('Simular execução','new-job','plus','primary')}</div>`}</section>`+notice('Sucesso de job e atualidade dos dados são fatos diferentes','Uma execução sem novidade mantém a fronteira anterior. Atrasos, indisponibilidade e qualidade têm indicação própria.');}
function review(){return `<div class="field review-picker"><label for="review-game">Modalidade em revisão</label><select id="review-game">${games.map(g=>`<option value="${g.slug}" ${g.slug===game().slug?'selected':''}>${g.name}</option>`).join('')}</select></div>`+pageHeading('Revisão de dados','Divergências precisam de contexto antes de uma decisão.','','ADMINISTRAÇÃO')+notice('Cenário demonstrativo de revisão','Não há uma divergência real nova sendo afirmada. Este percurso mostra os controles de decisão sem alterar o resultado de referência.','amber')+`<section class="card card-body"><div class="card-header"><div><h2>${game().name} · ${drawName(game(),latest(game()))}</h2><p>Referência preservada e candidato ainda não carregado</p></div>${badge(state.review==='pending'?'Revisão demonstrativa pendente':'Demonstração revisada',state.review==='pending'?'amber':'green')}</div><div class="two-col"><div><h3>Última referência preservada</h3><div style="margin-top:14px">${balls(latest(game()).main)}</div>${game().specialCount?`<div class="ball-group">${balls(latest(game()).special,true)}</div>`:''}<p class="muted small" style="margin-top:15px">${formatDate(latest(game()).date)} · ${game().sourceLabel}</p></div><div class="empty" style="border:1px dashed var(--line);border-radius:12px;padding:24px"><h3>Sem candidato real nesta demonstração</h3><p style="margin-top:10px">A interface de produção comparará os campos e suas fontes. Valores divergentes não são inventados para preencher esta tela.</p></div></div><div class="form-actions">${button('Registrar decisão demonstrativa','review-decision','check','primary')}</div></section>`;}
function account(){return pageHeading('Minha conta','Seu acesso e os controles de sessão.','','CONTA')+`<div class="two-col"><section class="card card-body"><h2>Acesso ao LottoBrain</h2><dl class="definition-list"><div><dt>Estado</dt><dd>${badge('Aprovado','green')}</dd></div><div><dt>Papel da jornada</dt><dd>${e(personaLabels[state.persona])}</dd></div><div><dt>Conteúdo</dt><dd>Seis loterias e recursos autorizados</dd></div><div><dt>Identidade</dt><dd>Google · simulação local</dd></div><div><dt>MFA</dt><dd>${isAdmin()?'Confirmado no cenário':'Obrigatório para administração'}</dd></div></dl><div class="form-actions">${button('Sair da conta','logout','logout')}</div></section><section class="card card-body"><h2>Recuperação e privacidade</h2><p class="muted" style="margin-top:12px">A recuperação das credenciais ocorre no Google. A aprovação do LottoBrain é uma decisão separada.</p><p class="muted small" style="margin-top:14px">Este protótipo não coleta nome, e-mail, senha, código real de MFA ou tokens. Mudanças demonstrativas são descartadas ao recarregar.</p><div class="form-actions">${button('Entender a recuperação','recovery','book')}</div></section></div>`;}
function login(){let title='Entre no seu espaço',text='Acesso privado aos dados, análises e experimentos das seis loterias.',status='';if(state.persona==='pending'){title='Solicitação enviada';text='Seu cadastro aguarda aprovação do administrador. Entrar com Google não libera os dados automaticamente.';status=badge('Aguardando aprovação','amber');}if(state.persona==='revoked'){title='Seu acesso foi revogado';text='Os dados do produto estão indisponíveis para esta conta. Você pode sair ou consultar o administrador.';status=badge('Acesso indisponível','red');}if(state.scenario==='expired'){title='Sua sessão expirou';text='Entre novamente para continuar. Os dados privados não são exibidos sem uma sessão válida.';status=badge('Sessão encerrada','amber');}return `${prototypeBar()}<main id="main" class="login-layout" tabindex="-1"><section class="login-story">${brand()}<div class="eyebrow" style="color:#9eb8df">DADOS · ESTATÍSTICA · EXPERIMENTOS</div><h1>Um espaço para entender cada sorteio.</h1><p>Explore históricos, acompanhe análises e compare métodos com contexto e rastreabilidade.</p><div class="login-visual" aria-hidden="true">${[40,62,49,82,55,100,69,85,110,74,98,120].map(h=>`<i style="--h:${h}px"></i>`).join('')}</div></section><section class="login-panel"><div class="login-content">${status?`<div style="margin-bottom:20px">${status}</div>`:''}<h2>${title}</h2><p>${text}</p>${state.persona==='pending'||state.persona==='revoked'?button('Sair da conta','logout','logout'): `<button class="button google-button" data-action="google"><span class="google-g" aria-hidden="true">G</span>Entrar com Google</button>`}<div class="steps"><div><b>1</b><div><strong>Confirme sua identidade</strong><p>Autenticação gerenciada pelo provedor.</p></div></div><div><b>2</b><div><strong>Aguarde a aprovação</strong><p>O administrador autoriza o acesso.</p></div></div><div><b>3</b><div><strong>Explore com privacidade</strong><p>Resultados e análises ficam restritos.</p></div></div></div><div class="login-bottom">Demonstração local: o botão não abre o Google nem envia dados. Use “Cenários e jornadas” para explorar cada estado.<br><button class="text-button" data-action="recovery">Como recuperar meu acesso?</button></div></div></section></main>`;}
function restricted(){return pageHeading('Acesso administrativo necessário','Esta área é reservada ao administrador com MFA.')+`<section class="card empty"><div class="empty-icon">${ico('lock')}</div><h2>${state.persona==='mfa'?'Confirme sua segunda etapa':'Você não tem permissão para esta ação'}</h2><p>${state.persona==='mfa'?'Antes de administrar usuários ou dados, conclua a verificação adicional. O código deste percurso é apenas demonstrativo.':'Ser usuário aprovado permite consultar o conteúdo, mas não administrar acessos ou configurações.'}</p>${state.persona==='mfa'?button('Demonstrar verificação MFA','mfa','shield','primary'):'<a class="button" href="#/visao-geral">Voltar à visão geral</a>'}</section>`;}

// Roteamento e composição da página
function render(focusTarget){route=parseRoute();document.documentElement.style.setProperty('--accent',game().color);document.title=`${route.path.startsWith('loterias')?game().name:route.path.startsWith('admin')?'Administração':'Meu espaço'} · LottoBrain — protótipo`;if(!isApproved()||route.path==='entrada'){app.innerHTML=login();return;}
let body;if(route.path.startsWith('admin')&&!isAdmin())body=restricted();else if(route.path==='visao-geral')body=overview();else if(route.path==='conta')body=account();else if(route.path==='admin/pessoas')body=people();else if(route.path==='admin/catalogo')body=catalog();else if(route.path==='admin/catalogo/nova')body=newLottery();else if(route.path==='admin/execucoes')body=jobs();else if(route.path==='admin/revisao')body=review();else if(route.path.startsWith('loterias/'))body=lottery();else body=overview();app.innerHTML=shell(body);if(focusTarget)document.querySelector(focusTarget)?.focus({preventScroll:true});}
function parseRoute(){const raw=(!location.hash||location.hash==='#main'?'#/loterias/mega_sena/resumo':location.hash).replace(/^#\/?/,'');const [path,q]=raw.split('?'),parts=path.split('/'),slug=games.some(g=>g.slug===parts[1])?parts[1]:games[0].slug,tab=['resumo','concursos','estatisticas','previsoes'].includes(parts[2])?parts[2]:'resumo';if(parts[0]==='loterias'&&q){const p=new URLSearchParams(q);if(validDate(p.get('from'))&&validDate(p.get('to'))&&p.get('from')<=p.get('to'))state.filters[slug]={from:p.get('from'),to:p.get('to'),limit:p.get('limit')==='10'?10:30};}return {path,slug,tab};}
function go(path,focus){if(path.startsWith('loterias/')&&!path.includes('?')&&focus?.startsWith('#tab-')){const f=state.filters[game().slug];if(f)path+='?'+new URLSearchParams({from:f.from,to:f.to,limit:String(f.limit)});}const hash='#/'+path;if(location.hash===hash)render(focus);else{state.page=0;pendingFocus=focus||'h1';location.hash=hash;}}
function closeDialog(){if(dialog.open)dialog.close();}

// Diálogos, explicações e detalhes
function showDialog(title,body,actions=''){returnFocus=document.activeElement;document.getElementById('dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title" tabindex="-1">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Fechar diálogo">${ico('close')}</button></div><div class="dialog-body">${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;if(!dialog.open)dialog.showModal();document.getElementById('dialog-title').focus();}
dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});
dialog.addEventListener('keydown',event=>{
  if(event.key!=='Tab')return;
  const controls=[...dialog.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length&&!el.hidden);
  if(!controls.length){event.preventDefault();return;}
  const index=controls.indexOf(document.activeElement);
  if(index<0||(event.shiftKey&&index===0)||(!event.shiftKey&&index===controls.length-1)){
    event.preventDefault();controls[event.shiftKey?controls.length-1:0].focus();
  }
});
const explanations={frequency:['Frequência dos números','Conta em quantos sorteios da janela cada número apareceu.','A contagem usa somente o componente selecionado e os filtros visíveis. Números empatados são ordenados pelo valor.','Frequência descreve a amostra; não representa probabilidade do próximo sorteio.'],sum:['Soma dos números principais','Ajuda a visualizar como a soma varia entre os sorteios do recorte.','Soma somente os números principais de cada sorteio, em ordem cronológica. Estrelas, trevos e bolas especiais não entram.','Compare dentro da mesma modalidade e regra. Uma faixa de soma observada não prevê a próxima.'],gap:['Ocorrência e intervalo no recorte','Mostra quando um número foi observado pela última vez.','O intervalo conta sorteios posteriores à ocorrência mais recente, dentro da janela. Ausência no recorte é desconhecida, não intervalo zero.','Um intervalo longo não torna um número mais provável. A janela não equivale ao histórico inteiro.'],sample:['Recorte de referência','Permite avaliar a interface usando resultados reais já preservados.','Há 30 sorteios por modalidade, com os componentes e valores oferecidos nas fontes. Filtros reduzem esse conjunto.','Não houve atualização externa, importação operacional ou aprovação de dataset de produção pelo protótipo.'],forecast:['Avaliação de previsões','O objetivo é buscar a melhor previsão mensurável possível.','Os métodos usarão cortes temporais, comparação com referências, métricas e orçamento de combinações equivalentes. A previsão emitida terá modelo, regra e horário.','Não há modelo treinado, métrica calculada nem probabilidade validada neste protótipo. Backtest e emissão futura serão mostrados separadamente.']};
function showInfo(key){const [title,purpose,calc,limit]=explanations[key]||explanations.sample;showDialog(title,`<h3>Para que serve</h3><p>${purpose}</p><h3>Como é calculado</h3><p>${calc}</p><h3>Como interpretar</h3><p>${limit}</p>`,button('Entendi','close-dialog','check','primary'));}
function tierLabel(label){return /^\d+$/.test(label)?`${label} acertos`:label.replace('0 or 1','1 ou nenhum trevo').replace(/(\d) números \+ 2$/,'$1 números + 2 trevos').replace(/(\d) números \+ 1$/,'$1 números + 1 trevo');}
function showDraw(id){const g=game(),d=g.draws.find(r=>r.id===id);if(!d)return;showDialog(`${g.name} · ${drawName(g,d)}`,`<p>${formatDate(d.date)} · fonte ${g.sourceLabel}</p><h3>Números principais</h3>${balls(d.main)}${g.specialCount?`<h3>${g.specialLabel}</h3>${balls(d.special,true)}`:''}${d.multiplier?`<p>Power Play publicado: ${d.multiplier}×</p>`:''}${d.doublePlay?`<h3>Double Play · série vinculada</h3>${balls(d.doublePlay.slice(0,5),false,true)}<div class="ball-group">${balls(d.doublePlay.slice(5),true,true)}</div><p>Campo presente nesta amostra OPEN-NY. Não representa coletor adicional habilitado.</p>`:''}<h3>Premiação publicada</h3>${d.tiers.length?`<p>${e(d.tiers[0].scope)} · valores por ganhador, conforme a fonte.</p><div class="table-wrap"><table><thead><tr><th>Faixa</th><th>Ganhadores</th><th>Por ganhador</th></tr></thead><tbody>${d.tiers.map(t=>`<tr><td>${e(tierLabel(t.label))}</td><td>${t.winners==null?'Não informado':fmt(t.winners)}</td><td>${money(t.amount,g.currency)}</td></tr>`).join('')}</tbody></table></div>`:'<p>As faixas financeiras não estão incluídas neste recorte da fonte OPEN-NY. Ausência não é prêmio zero.</p>'}`,button('Fechar detalhes','close-dialog','check','primary'));}

// Ações locais: nenhuma chamada de rede ou persistência
document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();document.getElementById('main')?.focus();return;}const target=event.target.closest('[data-action]');if(!target)return;const {action}=target.dataset;
if(action==='close-dialog'){closeDialog();return;}if(action==='scenarios'){showDialog('Cenários e jornadas',`<div class="scenario-note">Controles de revisão do protótipo. Não autenticam usuários, não acessam serviços e não alteram os dados de referência.</div><form id="scenario-form" class="scenario-grid" style="margin-top:18px"><div class="field"><label for="persona">Jornada de acesso</label><select id="persona" name="persona">${Object.entries(personaLabels).map(([value,label])=>`<option value="${value}" ${state.persona===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="scenario">Cenário de interface</label><select id="scenario" name="scenario">${Object.entries(scenarios).map(([value,label])=>`<option value="${value}" ${state.scenario===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="dialog-actions"><button class="button" type="button" data-action="reset">Restaurar demonstração</button><button class="button primary" type="submit">Aplicar cenário</button></div></form>`);return;}
if(action==='reset'){state.persona='member';state.scenario='normal';state.page=0;state.filters={};state.jobs=[];state.drafts=[];state.requests=[{id:'demo01',name:'Solicitação demonstrativa 01',status:'pending'}];state.review='pending';state.reviewSlug=null;state.component='main';closeDialog();go('loterias/mega_sena/resumo');render();return;}
if(action==='menu'){showDialog('Navegação',`<div class="mobile-nav">${brand()}${nav()}<button class="button" data-action="logout">${ico('logout')}Sair</button></div>`);return;}
if(action==='logout'){closeDialog();state.persona='anonymous';state.scenario='normal';go('entrada');render();return;}
if(action==='google'){state.persona='pending';state.scenario='normal';render();notify('Demonstração: solicitação de acesso criada, sem contato com o Google.');return;}
if(action==='recovery'){showDialog('Recuperar acesso',`<p>As credenciais são recuperadas no provedor Google. A aprovação de acesso ao LottoBrain continua com o administrador.</p><p>Se o acesso foi revogado, autenticar novamente não desfaz a revogação. Esta tela é uma demonstração e não envia e-mail.</p>`,button('Entendi','close-dialog','check','primary'));return;}
if(action==='source'){const g=game();showDialog('Origem e disponibilidade',`<p>Este protótipo usa recortes reais de referência, com 30 sorteios por modalidade, preservados na qualificação anterior.</p><dl class="definition-list">${games.map(x=>`<div><dt>${x.name}</dt><dd>${x.sourceLabel}<br><span class="small muted">${formatDate(x.draws[0].date,true)} a ${formatDate(latest(x).date,true)}</span></dd></div>`).join('')}</dl><p style="margin-top:18px">Sem coleta externa ou dados pessoais. Estatísticas são calculadas no recorte selecionado; modelos e métricas preditivas não são inventados.</p><p><a href="${g.sourceReference}" target="_blank" rel="noopener noreferrer">Consultar a fonte de ${g.name} ${ico('source')}</a></p>`,button('Fechar','close-dialog','check','primary'));return;}
if(action==='info'){showInfo(target.dataset.key);return;}
if(!isApproved()){render();return;}
if(action==='tab'){state.page=0;go(`loterias/${game().slug}/${target.dataset.tab}`,`#tab-${target.dataset.tab}`);return;}
if(action==='page'){state.page=Math.max(0,state.page+Number(target.dataset.delta));render();return;}
if(action==='component'){state.component=target.dataset.component;render(`[data-component="${state.component}"]`);return;}
if(action==='draw'){showDraw(target.dataset.id);return;}
if(action==='number'){const n=Number(target.dataset.number),component=target.dataset.component,draws=selectedDraws(),hits=draws.filter(d=>d[component].includes(n)),st=describe(draws,component==='main'?game().maximum:game().specialMaximum,component).frequencies[n-1];showDialog(`Número ${String(n).padStart(2,'0')}`,`<p>${component==='main'?'Números principais':game().specialLabel} · ${game().name}</p><dl class="definition-list"><div><dt>Ocorrências</dt><dd>${hits.length} em ${draws.length} sorteios</dd></div><div><dt>Sorteios desde a última ocorrência</dt><dd>${st.gap==null?'Desconhecido neste recorte':st.gap}</dd></div></dl><h3>Datas observadas</h3><p>${hits.length?hits.map(d=>formatDate(d.date,true)).join(' · '):'Não ocorreu dentro da janela selecionada.'}</p><p>Intervalo observado não é indicação de maior probabilidade futura.</p>`,button('Fechar','close-dialog','check','primary'));return;}
if(action==='resume'||action==='reset-filter'){state.scenario='normal';state.page=0;if(action==='reset-filter'){delete state.filters[game().slug];go(`loterias/${game().slug}/${route.tab}`);}render('#lottery-panel');return;}
if(action==='mfa'){showDialog('Verificação em duas etapas',`<p>Demonstração de interação. Não digite um código real: qualquer sequência de seis dígitos exercita o fluxo.</p><form id="mfa-form"><div class="field"><label for="mfa-code">Código demonstrativo de seis dígitos</label><input id="mfa-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off" required></div><p id="mfa-error" class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">Concluir demonstração</button></div></form>`);return;}
if(!isAdmin()){notify('Ação reservada ao administrador com MFA.');return;}
if(action==='approve-user'||action==='revoke-user'){const revoke=action==='revoke-user';showDialog(revoke?'Revogar acesso':'Aprovar solicitação',`<p>${revoke?'A revogação deve bloquear novas consultas e encerrar as sessões autorizadas.':'A aprovação permite acesso às seis loterias como usuário.'} Nesta demonstração nenhuma conta real é alterada.</p><form id="access-form" data-id="${target.dataset.id}" data-decision="${revoke?'revoked':'approved'}"><div class="field"><label for="access-reason">Motivo da decisão</label><textarea id="access-reason" name="reason" minlength="5" required placeholder="Registre o motivo demonstrativo"></textarea></div><p id="access-error" class="form-error" role="alert"></p><div class="dialog-actions"><button class="button" type="button" data-action="close-dialog">Cancelar</button><button class="button ${revoke?'danger':'primary'}" type="submit">${revoke?'Confirmar revogação':'Confirmar aprovação'}</button></div></form>`);return;}
if(action==='new-lottery'){go('admin/catalogo/nova');return;}
if(action==='catalog-detail'){const g=games.find(g=>g.slug===target.dataset.slug);showDialog(g.name,`<dl class="definition-list"><div><dt>Regra do recorte</dt><dd>${g.count}/${g.maximum}${g.specialCount?` + ${g.specialCount}/${g.specialMaximum}`:''}</dd></div><div><dt>Componente especial</dt><dd>${g.specialLabel||'Não se aplica'}</dd></div><div><dt>Fonte</dt><dd>${g.sourceLabel}</dd></div><div><dt>Moeda</dt><dd>${g.currency}</dd></div><div><dt>Dados exibidos</dt><dd>30 sorteios reais de referência</dd></div></dl><p style="margin-top:18px">Regra do recorte atual. O cadastro de produção preservará versões históricas e não alterará resultados anteriores.</p>`,button('Fechar','close-dialog','check','primary'));return;}
if(action==='activate-draft'){const d=state.drafts[Number(target.dataset.index)];showDialog('Revisar ativação',`<p><strong>${e(d.name)}</strong> · rascunho demonstrativo.</p><p>Uma ativação real exige regra aprovada, fonte/contrato qualificados, adaptador suportado e validação de cobertura. O protótipo não realizou essas verificações.</p><p>O botão abaixo demonstra somente a confirmação visual. Não inicia coleta nem cria resultados.</p>`,button('Cancelar','close-dialog','close')+button('Simular confirmação de ativação','confirm-activate','check','primary',`data-index="${target.dataset.index}"`));return;}
if(action==='confirm-activate'){state.drafts[Number(target.dataset.index)].active=true;closeDialog();render();notify('Ativação demonstrada. Nenhuma fonte ou coleta foi habilitada.');return;}
if(action==='new-job'){showDialog('Solicitar execução demonstrativa',`<p>Uma solicitação real executará em segundo plano. Aqui o fluxo muda apenas a lista desta sessão.</p><form id="job-form"><div class="scenario-grid"><div class="field"><label for="job-game">Modalidade</label><select id="job-game" name="game">${games.map(g=>`<option ${g.slug===game().slug?'selected':''}>${g.name}</option>`).join('')}</select></div><div class="field"><label for="job-kind">Intenção</label><select id="job-kind" name="kind"><option>Atualização limitada</option><option>Reconciliação diária</option><option>Experimento temporal</option></select></div><div class="dialog-actions"><button class="button" type="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">Simular solicitação</button></div></div></form>`);return;}
if(action==='finish-job'){state.jobs[Number(target.dataset.index)].done=true;render();notify('Conclusão simulada. Datas e resultados de referência não foram alterados.');return;}
if(action==='review-decision'){showDialog('Decisão de revisão',`<p>Esta é uma demonstração sem candidato real. O conjunto de referência não será alterado.</p><form id="review-form"><div class="field"><label for="review-choice">Decisão demonstrativa</label><select id="review-choice" name="choice"><option>Solicitar investigação adicional</option><option>Rejeitar observação candidata</option><option>Encaminhar correção para validação</option></select></div><div class="dialog-actions"><button class="button" type="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">Registrar demonstração</button></div></form>`);return;}
});

// Validação dos formulários de demonstração
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();const data=new FormData(form);
if(form.id==='scenario-form'){state.persona=data.get('persona');state.scenario=data.get('scenario');state.page=0;closeDialog();if(isApproved()){if(route.path==='entrada')go(isAdmin()?'admin/pessoas':'loterias/mega_sena/resumo');}render();notify('Cenário demonstrativo aplicado.');return;}
if(form.id==='filters-form'){const from=data.get('from'),to=data.get('to'),err=document.getElementById('filter-error');if(!validDate(from)||!validDate(to)||from>to){err.hidden=false;err.textContent='A data inicial deve ser anterior ou igual à final.';document.getElementById('from-date').setAttribute('aria-invalid','true');return;}state.filters[game().slug]={from,to,limit:Number(data.get('limit'))};state.page=0;const q=new URLSearchParams({from,to,limit:String(data.get('limit'))});go(`loterias/${game().slug}/${route.tab}?${q}`);render();return;}
if(form.id==='mfa-form'){if(!/^\d{6}$/.test(data.get('code'))){document.getElementById('mfa-error').textContent='Informe seis dígitos demonstrativos.';return;}state.persona='admin';closeDialog();render();notify('MFA demonstrado. Nenhum código foi verificado em um provedor.');return;}
if(!isAdmin())return;
if(form.id==='access-form'){if(data.get('reason').trim().length<5){document.getElementById('access-error').textContent='Informe um motivo com pelo menos cinco caracteres.';return;}state.requests.find(r=>r.id===form.dataset.id).status=form.dataset.decision;closeDialog();render();notify('Decisão demonstrativa registrada apenas nesta sessão.');return;}
if(form.id==='lottery-form'){const value={name:data.get('name').trim(),slug:data.get('slug').trim(),count:Number(data.get('count')),maximum:Number(data.get('maximum')),specialCount:Number(data.get('specialCount')),specialMaximum:Number(data.get('specialMaximum')),specialLabel:data.get('specialLabel').trim(),currency:data.get('currency'),profile:data.get('profile'),timezone:data.get('timezone'),policy:data.get('policy'),active:false};const error=validateDraft(value,[...games,...state.drafts]);if(error){document.getElementById('lottery-error').textContent=error;return;}state.drafts.push(value);go('admin/catalogo');notify('Rascunho demonstrativo salvo. Nenhuma coleta foi criada.');return;}
if(form.id==='job-form'){state.jobs.push({game:data.get('game'),kind:data.get('kind'),done:false});closeDialog();go('admin/execucoes');render();notify('Solicitação demonstrativa adicionada à lista.');return;}
if(form.id==='review-form'){state.review='reviewed';closeDialog();render();notify('Decisão demonstrada. A referência original permanece intacta.');}
});
document.addEventListener('keydown',event=>{const target=event.target;if(target.getAttribute('role')!=='tab')return;const keys=['ArrowRight','ArrowLeft','Home','End'];if(!keys.includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')],i=tabs.indexOf(target);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();});
document.addEventListener('click',event=>{if(event.target.closest('a[href^="#/"]')&&dialog.open)closeDialog();});
document.addEventListener('change',event=>{if(event.target.id==='review-game'){state.reviewSlug=event.target.value;state.review='pending';render('#review-game');}});
window.addEventListener('hashchange',()=>{state.page=0;closeDialog();render(pendingFocus||'h1');pendingFocus=null;window.scrollTo({top:0,behavior:'instant'});});
window.LottoPrototype={getState:()=>({persona:state.persona,scenario:state.scenario,route:{...route},drafts:state.drafts.length,jobs:state.jobs.length,requests:state.requests.map(r=>({...r}))}),reference:metadata};
render();
})();
